228		router := NewRouter(openTestStore(t))
229	
230		const writers = 16
231		codes := make([]int, writers)
232		seqs := make([]float64, writers)
233		var wg sync.WaitGroup
234		for i := 0; i < writers; i++ {
235			wg.Add(1)
236			go func(i int) {
237				defer wg.Done()
238				recorder := postEventBody(t, router, validEventBody())
239				codes[i] = recorder.Code
240				if recorder.Code == http.StatusCreated {
241					seqs[i] = decodeEvent(t, recorder)["seq"].(float64)
242				}
243			}(i)
