569			if event["account"] != tc.wantAccount {
570				t.Fatalf("%s: account = %q, want %q", tc.name, event["account"], tc.wantAccount)
571			}
572			// The hash is computed over the decoded text, so an escaped
573			// surrogate pair and the same character submitted directly
574			// produce identical hashes at identical chain positions.
575			seq := int64(i + 1)
576			want := wantHash(seq, tc.wantAccount, "o", "r", "ok", "2026-10-05T00:00:00Z", prevHash)
577			if event["hash"] != want {
578				t.Fatalf("%s: hash = %v, want %v", tc.name, event["hash"], want)
579			}
580			prevHash = event["hash"].(string)
581		}
582	
583		// What was persisted matches the decoded text exactly.
584		stored := readStoredEvents(t, path)
585		if len(stored) != len(cases) {
586			t.Fatalf("stored %d events, want %d", len(stored), len(cases))
587		}
588		for i, tc := range cases {
589			if stored[i].account != tc.wantAccount {
590				t.Fatalf("%s: stored account = %q, want %q", tc.name, stored[i].account, tc.wantAccount)
591			}
592		}
593	}
594	
595	func TestPostEventRejectedEncodingLeavesChainUntouched(t *testing.T) {
596		path := filepath.Join(t.TempDir(), "service.db")
597		st, err := store.Open(path)
598		if err != nil {
599			t.Fatalf("open: %v", err)
600		}
601		defer st.Close()
602		router := NewRouter(st)
603	
604		// One valid record so seq 1 exists and seq 9 is a gap.
605		seed := postEventBody(t, router, validEventBody())
606		if seed.Code != http.StatusCreated {
607			t.Fatalf("seed: status = %d (%s)", seed.Code, seed.Body.String())
608		}
609		first := decodeEvent(t, seed)
610	
611		// Invalid UTF-8 bytes and unpaired surrogates are rejected no matter
612		// what seq the request carries: omitted, already existing, or a gap.
613		accounts := []string{
614			`"a` + "\xff" + `"`,    // invalid UTF-8 byte
615			`"` + "\xe4\xb8" + `"`, // truncated multibyte character
616			`"\uD83D"`,             // lone high surrogate
617			`"\uDE00"`,             // lone low surrogate
618			`"\uDE00\uD83D"`,       // reversed pair
619		}
620		for _, account := range accounts {
621			for _, seq := range []string{"", `,"seq":1`, `,"seq":9`} {
622				body := `{"account":` + account +
623					`,"operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"` + seq + `}`
624				wantInvalidInput(t, router, body)
625			}
626		}
627	
628		// The rejections consumed no sequence number and moved no chain tail.
629		stored := readStoredEvents(t, path)
630		if len(stored) != 1 || stored[0].hash != first["hash"] {
631			t.Fatalf("stored events = %+v, want only the seed record", stored)
632		}
633	
634		// The next valid append continues from the original chain tail.
635		recorder := postEventBody(t, router, validEventBody())
636		if recorder.Code != http.StatusCreated {
637			t.Fatalf("status = %d (%s)", recorder.Code, recorder.Body.String())
638		}
639		second := decodeEvent(t, recorder)
640		if second["seq"] != float64(2) || second["prev_hash"] != first["hash"] {
641			t.Fatalf("next = %v, want seq 2 chained to %v", second, first["hash"])
642		}
643		stored = readStoredEvents(t, path)
644		if len(stored) != 2 || stored[1].hash != second["hash"] {
645			t.Fatalf("stored events after valid append = %+v", stored)
646		}
647	}
